  str_season_maze_s3_help_title_508 = "Ruang Ramalan Dream",
  str_season_maze_s3_help_title_509 = "Perdagangan Alam Mimpi",
  str_season_maze_s3_help_title_510 = "Safe Dream Realm",
  str_season_maze_s3_help_title_511 = "Teleportasi Alam Mimpi",
  str_season_maze_s3_help_title_512 = "Pertemuan Alam Mimpi",
  str_season_maze_s3_help_title_513 = "Pemanggilan Alam Mimpi",
  str_season_maze_s3_help_title_601 = "Aurorian",
  str_season_maze_s3_help_title_602 = "Gear Impian",
  str_season_maze_s3_help_title_603 = "Kartu Ramalan Mimpi",
  str_season_maze_s3_help_title_604 = "Orb Mimpi",
  str_season_maze_s3_help_title_605 = "Item Bantuan Mimpi",
  str_season_maze_s3_help_title_701 = "Jenis Orb Mimpi",
  str_season_maze_s3_help_title_702 = "Energi Orb Mimpi",
  str_season_maze_s3_help_title_703 = "Level Dream Orb",
  str_season_maze_s3_help_title_704 = "Sintesis Orb Mimpi",
  str_season_maze_s3_help_title_705 = "Transmisi Orb Mimpi",
  str_season_maze_s3_help_disc_101 = "Elemen-elemen tidak stabil dari mimpi masa lalu masih mengendap di alam mimpi, siap untuk menyerang kenyataan kapan saja. Dengan bantuan Enlightener, Navigator sekarang dapat kembali ke dalam mimpi untuk berpartisipasi dalam berbagai acara eksplorasi, meningkatkan kekuatan mereka dalam mimpi. Dengan mengalahkan Ultimate Dream Devourer, ada kesempatan untuk mengembalikan stabilitas energi mimpi.",
  str_season_maze_s3_help_disc_102 = "Navigator akan memimpin Enlightener, memanfaatkan kekuatan Kartu Divinasi Mimpi, untuk menelusuri berbagai alam mimpi dan memicu peristiwa di dalamnya. Selama penjelajahan, Navigator dapat memanggil Aurorian dan mengumpulkan Dream Gear, Dream Orbs, dan sumber daya mimpi lainnya untuk meningkatkan kemampuan mereka. Setelah akhirnya mengalahkan Dream Devourer dan Ultimate Dream Devourer, Daydream dapat diselesaikan, menghasilkan hadiah yang kaya.",
  str_season_maze_s3_help_disc_201 = "Enlightener akan mengevaluasi kinerja Navigator dalam mimpi dan mencatat skor mereka. Kumpulkan skor yang cukup untuk mendapatkan hadiah yang sesuai.",
  str_season_maze_s3_help_disc_202 = "Setelah setiap eksplorasi, Enlightener akan mencatat skor yang sesuai berdasarkan Level Mimpi dan Kemajuan Eksplorasi. Akumulasi skor cukup untuk mencapai tonggak tertentu dan mendapatkan hadiah yang sesuai. Selain itu, kamu bisa mendapatkan skor ekstra dengan menyelesaikan Quest Mimpi.",
  str_season_maze_s3_help_disc_203 = "Ketika skor terakumulasi kamu mencapai tonggak tertentu, kamu dapat mengklaim hadiah yang sesuai. Lebih banyak tonggak hadiah akan dibuka pada interval reguler.",
  str_season_maze_s3_help_disc_204 = "Dalam mimpi, ada berbagai Quest Mimpi yang dapat diambil, yang memberikan skor tambahan saat selesai.",
  str_season_maze_s3_help_disc_301 = "Mimpi dibagi menjadi berbagai level. Semakin tinggi levelnya, semakin sulit tantangannya, dan semakin banyak skor yang diperoleh setelah selesai. Dalam layar Level Mimpi, Anda dapat melihat Ultimate Dream Devourer yang aktif di setiap level untuk merancang strategi eksplorasi Anda sesuai itu.",
  str_season_maze_s3_help_disc_302 = "Kamu akan memulai di Level Mimpi 1 dan membuka level berikutnya setelah menyelesaikan level saat ini, dan beberapa level akan terbuka seiring waktu. Fitur Dream Orb akan tersedia saat Level Mimpi 3 dibuka, memberikan dukungan untuk eksplorasi kamu.",
  str_season_maze_s3_help_disc_303 = "Ketika memasuki mimpi, kamu perlu memilih 4 Aurorian untuk membentuk formasi awal untuk eksplorasi. Aurorian yang dikerahkan akan mewarisi Level Breakthrough mereka dari luar mimpi tetapi tidak akan mewarisi statistik atau level yang lainnya.",
  str_season_maze_s3_help_disc_304 = "Aurorian tertentu tidak bisa digunakan di Echoes of a Dream, juga tidak bisa dipanggil selama eksplorasi; daftar Aurorian ini berubah setiap kali Echoes of a Dream muncul.",
  str_season_maze_s3_help_disc_401 = "Selama eksplorasi, Navigator dapat mengendalikan diri mereka sendiri dan membawa Enlightener ke perjalanan.",
  str_season_maze_s3_help_disc_402 = "Enlightener membagi mimpi menjadi berbagai Dream Realm berdasarkan fluktuasi energi mimpi. Navigator hanya dapat berpindah antara Dream Realm, masing-masing memicu peristiwa yang berbeda.",
  str_season_maze_s3_help_disc_403 = "Navigator dapat menggunakan kekuatan Kartu Divinasi Mimpi untuk berpindah antara berbagai Alam Mimpi. Langkah Aksi pada Kartu Divinasi Mimpi menentukan jumlah Alam Mimpi yang dapat dilalui Navigator, dengan beberapa kartu juga menawarkan sumber daya tambahan atau efek khusus. Di awal setiap putaran, Enlightener akan mengambil sejumlah Kartu Divinasi Mimpi dari dek kartu, dan Navigator dapat memilih satu untuk memainkannya atau menyeretnya langsung ke layar untuk menjalankan efeknya.",
  str_season_maze_s3_help_disc_404 = "Navigator dapat mengumpulkan berbagai sumber daya di dalam mimpi. Dream Coins dapat membeli berbagai item, Dream EXP meningkatkan Level Mimpi, Dream Interest meningkatkan jumlah Dream Coins yang diperoleh per putaran, dan Cyclique menjamin keamanan dan stabilitas navigasi di dalam mimpi.",
  str_season_maze_s3_help_disc_405 = "Di Tool Pouch, kamu bisa melihat Aurorian yang dikerahkan dalam eksplorasi ini, Dream Gear yang diperoleh, dan Dream Divination Cards yang ditambahkan ke deck.",
  str_season_maze_s3_help_disc_406 = "Kenangan dan emosi yang ditinggalkan oleh pemimpi asli dibungkus lapis demi lapis dalam energi mimpi, membentuk Dream Orbs. Navigator dapat melihat Dream Orbs yang diperoleh dalam eksplorasi ini di sini dan memasang atau mensintesisnya.",
  str_season_maze_s3_help_disc_407 = "Dream Devourers akan menyerang Navigator setelah sejumlah putaran tertentu. Hanya dengan mengalahkan Dream Devourers, Navigator dapat melanjutkan eksplorasi mimpi mereka. The Ultimate Dream Devourer adalah pertemuan terakhir. Kalahkan untuk menyelesaikan eksplorasi ini, mendapatkan skor berdasarkan level mimpi dan kemajuan eksplorasi.",
  str_season_maze_s3_help_disc_408 = "Di sini, Navigator bisa melihat kondisi medan tempur dan informasi musuh dari pertempuran ini, yang memungkinkan mereka untuk menyesuaikan taktik mereka. Navigator bisa mendapatkan hadiah yang sesuai setelah menyelesaikan tantangan, tetapi jika gagal, mereka perlu menghabiskan Resonance untuk mencoba lagi.",
  str_season_maze_s3_help_disc_409 = "EXP Dream yang diperoleh selama eksplorasi dapat meningkatkan Level Dream Navigator, meningkatkan level Aurorian dan peralatan serta membuka Kartu Divinasi Dream dan Item Bantuan Dream baru untuk memperkuat Daydreams.",
  str_season_maze_s3_help_disc_501 = "Navigator dapat memasuki Dangerous Dream Realms untuk bertempur melawan musuh dan mendapatkan kesempatan untuk memilih satu Dream Gear setelah kemenangan.",
  str_season_maze_s3_help_disc_502 = "Ketika Navigator memasuki Unknown Dream Realms, acara acak akan dipicu. Beberapa acara memerlukan pengambilan 3 Kartu Divinasi Mimpi dan penentuan jumlah poin. Keberhasilan dalam penentuan memberikan hadiah yang sesuai.",
  str_season_maze_s3_help_disc_503 = "Ketika memasuki Resource Dream Realms, Navigator dapat memperoleh berbagai jenis hadiah sumber daya, termasuk Dream Coins, Dream EXP, dan Dream Orbs. Semakin banyak langkah yang diambil sebelum memasuki Dream Realm ini, semakin banyak hadiah yang didapatkan.",
  str_season_maze_s3_help_disc_504 = "Setelah memasuki Unexplored Dream Realms, Navigator bisa mengirimkan Aurorian apa saja untuk menyelesaikan quest dan mendapatkan reward. Navigator juga bisa memilih berapa banyak ronde mereka akan di-dispatch. Semakin banyak ronde, semakin besar rewardnya. Selama di-dispatch, Aurorian tidak bisa terlibat dalam pertempuran dan akan otomatis kembali setelah quest mereka berakhir.",
  str_season_maze_s3_help_disc_505 = "Ketika memasuki Treasure Dream Realms, Navigator dapat memilih satu hadiah dari berbagai pilihan untuk diperoleh.",
  str_season_maze_s3_help_disc_506 = "Saat memasuki Terowongan Realm Mimpi, Navigator menunda serangan Dream Devourer sebanyak 1 putaran.",
  str_season_maze_s3_help_disc_507 = "Memasuki Realm Mimpi Kosong tidak akan memicu efek apa pun.",
  str_season_maze_s3_help_disc_508 = "Dalam Realm Mimpi Divinasi, Navigator dapat menghabiskan Dream Coins untuk mereset atau menghapus Kartu Divinasi Mimpi yang ada.",
  str_season_maze_s3_help_disc_509 = "Di Trade Dream Realms, Navigator bisa mengklaim satu Dream Orb gratis dan membeli lebih banyak jika diperlukan.",
  str_season_maze_s3_help_disc_510 = "Safe Dream Realm adalah tempat Navigator beristirahat, memungkinkan mereka untuk memanggil Aurorian, membeli barang, membeli obat, atau menghidupkan kembali Aurorian untuk meningkatkan kekuatan mereka. Selain itu, menyuntikkan Dream Coins ke dalam Dream Forge dapat membuka item yang lebih kuat untuk tantangan di masa depan.",
  str_season_maze_s3_help_disc_511 = "Dalam Teleportasi Realm Impian, kamu akan langsung diteleportasi ke Realm Impian mereka tanpa melewati mimpi lain. Harap perhatikan bahwa teleportasi hanya berlaku satu arah saja.",
  str_season_maze_s3_help_disc_512 = "Di Dream Realm Gathering, kamu bisa membeli Dream Gear.",
  str_season_maze_s3_help_disc_513 = "Dalam Summoning Dream Realm, kamu bisa memilih elemen dan memanggil Aurorian dari elemen yang sesuai dalam arah target. Setelah dipilih, elemen tidak bisa diubah untuk summoning yang diberikan.",
  str_season_maze_s3_help_disc_601 = "Navigator dapat memanggil Aurorian untuk bergabung dalam formasi mereka. Aurorian yang diterjunkan akan mewarisi Level Breakthrough mereka dari luar mimpi tetapi tidak akan mewarisi statistik atau level lain yang telah dikembangkan. Tingkatkan Level Mimpi Anda untuk meningkatkan level Aurorian dan peralatan mereka dalam mimpi.",
  str_season_maze_s3_help_disc_602 = "Dream Gear adalah pengetahuan berharga dan relik berharga yang ditinggalkan oleh Dream Wayfarers yang cukup berani untuk menjelajahi mimpi di sungai waktu. Ini dapat memicu berbagai efek untuk membantu navigator dalam Daydream mereka.",
  str_season_maze_s3_help_disc_603 = "Navigator dapat menggunakan kekuatan Kartu Divinasi Mimpi untuk berpindah antara Dunia Mimpi yang berbeda. Langkah Aksi pada Kartu Divinasi Mimpi menentukan jumlah Dunia Mimpi yang dapat dilalui Navigator, dengan beberapa kartu juga menawarkan sumber daya tambahan atau efek khusus, termasuk tetapi tidak terbatas pada Dream Coins, Dream Interest, Dream EXP, Cyclique, dll.",
  str_season_maze_s3_help_disc_604 = "Kenangan dan emosi yang ditinggalkan oleh pemimpi asli dibungkus lapis demi lapis dalam energi mimpi, membentuk Dream Orbs. Dream Orbs dapat meningkatkan kekuatan tempur Navigator dalam mimpi, jadi hati-hati jangan sampai Dream Devourer mengambilnya!",
  str_season_maze_s3_help_disc_605 = "Ketika dibawa ke dalam mimpi, barang-barang dunia nyata terkadang terkikis oleh energi mimpi, membentuk Item Bantuan Mimpi. Setiap Item Bantuan Mimpi memiliki efek bantuan yang unik. Gunakan mereka dengan bijaksana untuk mendapatkan dukungan dalam penjelajahan Anda.",
  str_season_maze_s3_help_disc_701 = "Ada 3 jenis Dream Orbs: Skill Orbs, Enhancement Orbs, dan Charging Orbs. Skill Orbs digunakan untuk melempar skill dalam pertempuran, Enhancement Orbs meningkatkan Dream Orbs lain yang dipasang, dan Charging Orbs memberikan peningkatan Energy lebih cepat dalam pertempuran.",
  str_season_maze_s3_help_disc_702 = "Dalam pertempuran, kamu mendapatkan 1 poin Energi Orb Mimpi untuk setiap ubin yang dipindahkan dan dihubungkan oleh Aurorianmu. Setelah menghubungkan ubin, jika kamu memiliki Energi lebih banyak dari kebutuhan Energi Orb Mimpi kamu, keterampilan dari Orb Mimpi yang kamu pasang akan dilemparkan secara berurutan dari kiri ke kanan.",
  str_season_maze_s3_help_disc_703 = "Dream Orb tersedia dalam 4 level dan bisa di-upgrade hingga menjadi Dream Orb Bintang 3. Semakin tinggi level Dream Orb, semakin kuat efeknya.",
  str_season_maze_s3_help_disc_704 = "Dua Dream Orb dengan level yang sama dapat disintesis untuk mendapatkan Dream Orb level berikutnya. Jika dua Dream Orb memiliki nama yang sama, mereka akan menghasilkan Dream Orb yang sama dengan level yang lebih tinggi. Jika dua Dream Orb berbeda, mereka akan menghasilkan Dream Orb acak dengan level yang lebih tinggi.",
  str_season_maze_s3_help_disc_705 = "Setelah setiap tantangan Echoes of a Dream berakhir, 5 Dream Orbs berlevel tertinggi yang dipasang dapat disimpan untuk tantangan berikutnya. Ketika kurang dari lima Dream Orbs yang dipasang, Dream Orbs berlevel tertinggi di ransel Anda akan dipertahankan. Dream Orbs yang dipertahankan akan direset menjadi Lv. 1.",
  str_season_maze_s3_guide_warn_90021101 = "Di Unexplored Dream Realms, Navigator bisa mengirimkan Aurorian apa saja untuk menyelesaikan quest dan mendapatkan reward. Navigator juga bisa memilih berapa banyak ronde mereka akan di-dispatch. Semakin banyak ronde, semakin besar rewardnya. Saat di-dispatch, Aurorian tidak bisa terlibat dalam pertempuran dan akan otomatis kembali setelah quest mereka berakhir.",
  str_season_maze_s3_guide_warn_90021102 = "Ketuk di sini untuk memilih Aurorian mana saja untuk di-dispatch. Aurorian yang di-dispatch tidak bisa ditambahkan ke susunan pertempuran dan akan otomatis kembali setelah quest mereka berakhir.",
  str_season_maze_s3_mail_gm_season = "Gema dari Sebuah Mimpi",
  str_season_maze_s3_mail_title_season = "Reward yang Belum Diklaim",
  str_season_maze_s3_mail_detail_season = "Event Echoes of a Dream telah berakhir! Berikut adalah reward yang gagal kamu klaim selama event berlangsung!"
}
